SELECT 
FROM res_account
WHERE 1=1

	AND  user_name like CONCAT('%',#{userName},'%')


	AND  platform_id = #{platformId}


	AND  user_id = #{userId}


	AND  main_account = #{mainAccount}

ORDER BY account_sort

SELECT 
FROM res_account
WHERE user_id = #{userId}
AND platform_id = #{platformId}
AND main_account = 1
LIMIT 1
